using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [ClassInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = CreateReportingConfiguration();
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        var reportStore = new DiskBasedReportingStorage(
            storageRootPath: Path.Combine("TestResults", "EvaluationReports"));

        return new ReportingConfiguration(evaluators, reportStore);
    }

    [TestMethod]
    public async Task ChatResponse_MeetsQualityThresholds()
    {
        await using var appHost =
            await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await appHost.BuildAsync();
        await app.StartAsync();

        var chatClient = app.Services.GetRequiredService<IChatClient>();

        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(ChatResponse_MeetsQualityThresholds));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is .NET Aspire and how does it help with cloud-native development?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        await scenario.EvaluateAsync(messages, response);

        foreach (var metric in scenario.GetAllMetrics())
        {
            if (metric is NumericMetric numericMetric)
            {
                Assert.IsTrue(
                    numericMetric.Value >= 3,
                    $"Metric '{metric.Name}' scored {numericMetric.Value}, expected >= 3");
            }
        }
    }

    [TestMethod]
    public async Task ChatResponse_HandlesFollowUp()
    {
        await using var appHost =
            await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await appHost.BuildAsync();
        await app.StartAsync();

        var chatClient = app.Services.GetRequiredService<IChatClient>();

        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(ChatResponse_HandlesFollowUp));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain dependency injection in one sentence."),
        };

        var response = await chatClient.GetResponseAsync(messages);

        messages.AddRange(response.Messages);
        messages.Add(new ChatMessage(ChatRole.User, "Can you give me a short code example?"));

        var followUpResponse = await chatClient.GetResponseAsync(messages);

        await scenario.EvaluateAsync(messages, followUpResponse);

        foreach (var metric in scenario.GetAllMetrics())
        {
            if (metric is NumericMetric numericMetric)
            {
                Assert.IsTrue(
                    numericMetric.Value >= 3,
                    $"Metric '{metric.Name}' scored {numericMetric.Value}, expected >= 3");
            }
        }
    }
}

